/**
 * BooKi - Özel Alan Adı (tenant self-service custom domain) page.
 *
 * Talks to Custom_domain.php. Once DNS is verified, this polls status()
 * every few seconds waiting for the host-side worker (scripts/domain-
 * worker.sh) to actually provision the certificate/nginx server block and
 * flip the tenant's status to 'active' - see Custom_domain.php's docblock
 * for the full three-stage trust boundary this crosses.
 */
(function () {
    'use strict';

    const $page = $('#custom-domain-page');
    if (!$page.length) {
        return;
    }

    const POLL_MS = 6000;
    let pollTimer = null;

    const STATUS_META = {
        none: {label: 'Alan adı eklenmedi', badge: 'bg-secondary'},
        pending_dns: {label: 'DNS bekleniyor', badge: 'bg-warning text-dark'},
        dns_verified: {label: 'DNS doğrulandı - etkinleştiriliyor', badge: 'bg-info text-dark'},
        provisioning: {label: 'Etkinleştiriliyor', badge: 'bg-info text-dark'},
        active: {label: 'Aktif', badge: 'bg-success'},
        failed: {label: 'Hata', badge: 'bg-danger'},
    };

    function csrf() {
        return vars('csrf_token');
    }

    function renderStatus(state) {
        const meta = STATUS_META[state.status] || STATUS_META.none;
        $('#cd-status-badge').text(meta.label).attr('class', 'badge ' + meta.badge);

        let body = '';
        if (state.status === 'active' && (state.domain || $page.data('active-domain'))) {
            state.domain = state.domain || $page.data('active-domain');
            body = `<p class="mb-0"><i class="fas fa-check-circle text-success me-2"></i>Hesabınız şu anda <strong>${state.domain}</strong> adresinden erişilebilir.</p>`;
        } else if (state.status === 'dns_verified' || state.status === 'provisioning') {
            body = `<p class="mb-0"><i class="fas fa-hourglass-half text-info me-2"></i><strong>${state.pending_domain || ''}</strong> için DNS doğrulandı, sertifika ve yönlendirme otomatik olarak hazırlanıyor. Bu sayfa kendiliğinden güncellenecek.</p>`;
        } else if (state.status === 'pending_dns') {
            body = `<p class="mb-0"><i class="fas fa-clock text-warning me-2"></i><strong>${state.pending_domain || ''}</strong> için DNS kayıtlarının eklenmesi bekleniyor.</p>`;
        } else if (state.status === 'failed') {
            const err = state.last_error || $page.data('last-error');
            body = `<p class="mb-1"><i class="fas fa-triangle-exclamation text-danger me-2"></i>Etkinleştirme başarısız oldu.</p><p class="text-muted small mb-0">${err || ''}</p>`;
        } else {
            body = '<p class="text-muted mb-0">Henüz bir özel alan adı eklenmedi.</p>';
        }
        $('#cd-status-body').html(body);

        $('#cd-request-card').toggleClass('d-none', state.status !== 'none' && state.status !== 'failed');
        $('#cd-dns-card').toggleClass('d-none', !['pending_dns', 'dns_verified', 'provisioning'].includes(state.status));
    }

    function showDnsInstructions(data) {
        $('#cd-txt-host').text(data.txt_host);
        $('#cd-txt-value').text(data.txt_value);
        $('#cd-cname-host').text(data.domain);
        $('#cd-cname-target').text(data.cname_target);
        $('#cd-a-target').text(data.a_target);
        $('#cd-dns-card').removeClass('d-none');
        $('#cd-request-card').addClass('d-none');
    }

    function startPolling() {
        stopPolling();
        pollTimer = setInterval(poll, POLL_MS);
    }

    function stopPolling() {
        if (pollTimer) {
            clearInterval(pollTimer);
            pollTimer = null;
        }
    }

    function poll() {
        $.get(App.Utils.Url.siteUrl('custom_domain/status')).done((response) => {
            if (!response.success) {
                return;
            }
            renderStatus(response);
            if (response.status === 'active' || response.status === 'none') {
                stopPolling();
            }
        });
    }

    $('#cd-request-btn').on('click', function () {
        const domain = $('#cd-domain-input').val().trim();
        const $btn = $(this);
        const $err = $('#cd-request-error').addClass('d-none');

        if (!domain) {
            $err.text('Lütfen bir alan adı girin.').removeClass('d-none');
            return;
        }

        $btn.prop('disabled', true);

        $.post(App.Utils.Url.siteUrl('custom_domain/request_domain'), {csrf_token: csrf(), domain})
            .done((response) => {
                if (response.success) {
                    showDnsInstructions(response);
                    renderStatus({status: 'pending_dns', pending_domain: response.domain});
                    startPolling();
                } else {
                    $err.text(response.message || 'Bir hata oluştu.').removeClass('d-none');
                }
            })
            .fail((xhr) => {
                $err.text(xhr.responseJSON?.message || 'Bir hata oluştu.').removeClass('d-none');
            })
            .always(() => $btn.prop('disabled', false));
    });

    $('#cd-verify-btn').on('click', function () {
        const $btn = $(this);
        const $result = $('#cd-verify-result').removeClass('d-none alert-success alert-danger');

        $btn.prop('disabled', true);
        $result.addClass('alert-info').removeClass('d-none').text('Kontrol ediliyor…');

        $.post(App.Utils.Url.siteUrl('custom_domain/verify_domain'), {csrf_token: csrf()})
            .done((response) => {
                $result.removeClass('alert-info alert-success alert-danger');
                $result.addClass(response.success ? 'alert-success' : 'alert-danger').text(response.message || '');

                if (response.success) {
                    renderStatus({status: response.status, pending_domain: $('#cd-domain-input').val().trim()});
                    startPolling();
                }
            })
            .fail((xhr) => {
                $result.removeClass('alert-info alert-success').addClass('alert-danger').text(xhr.responseJSON?.message || 'Bir hata oluştu.');
            })
            .always(() => $btn.prop('disabled', false));
    });

    $('#cd-cancel-btn').on('click', function () {
        if (!window.confirm('Bekleyen alan adı talebini iptal etmek istediğinize emin misiniz?')) {
            return;
        }

        $.post(App.Utils.Url.siteUrl('custom_domain/cancel_domain'), {csrf_token: csrf()}).done((response) => {
            if (response.success) {
                stopPolling();
                window.location.reload();
            }
        });
    });

    // Initial render from server-supplied state (data attributes on the page root) - a reload while
    // status is already pending_dns/dns_verified must still show the DNS record table, not just the
    // status card, so the tenant can go copy the records again without re-submitting the form.
    const initialStatus = $page.data('status');
    const initialDomain = $page.data('pending-domain');

    renderStatus({status: initialStatus, pending_domain: initialDomain, last_error: $page.data('last-error')});

    if (['pending_dns', 'dns_verified', 'provisioning'].includes(initialStatus) && initialDomain) {
        showDnsInstructions({
            txt_host: '_ki-verify.' + initialDomain,
            txt_value: $page.data('txt-value'),
            domain: initialDomain,
            cname_target: $page.data('canonical-target'),
            a_target: $page.data('a-target'),
        });
        startPolling();
    }
})();
